SELECT ?highestStation ?highestElevation ?lowestStation ?lowestElevation ?distanceMeters
WHERE {
  GRAPH <hydroturtle/camels_gb> {
    {
      SELECT ?highestStation ?highestElevation
      WHERE {
        ?highestStation hyobs:meanElevation ?highestElevation .
        FILTER (datatype(?highestElevation) = xsd:decimal || datatype(?highestElevation) = xsd:double || datatype(?highestElevation) = xsd:integer)
      }
