    ?lowestStation geo:hasGeometry ?lowestGeom .

    ?highestGeom geo:asWKT ?highestWKT .
    ?lowestGeom geo:asWKT ?lowestWKT .

    FILTER( ?highestStation != ?lowestStation )

    BIND(
      bif:st_distance(
        bif:st_geomfromtext(?highestWKT),
